Do not provide any other text or markdown fences.

Here is the original GNU C++11 code you have to translate:
<original_code>
#include <algorithm>
#include <iostream>
#include <cstdio>
#include <vector>
#include <deque>
#include <queue>
#include <cstring>
using namespace std;

struct Edge { int to, rev, cap; };
vector<Edge> G[2020];
int level[2020], iter[2020];
int ir[20][20], sc[20][20], pc[20][20];
char s[20][20], p[20][20];
int dd[20][20];
int dx[5] = {0,1,-1,0};
int dy[5] = {1,0,0,-1};
vector<int> ns[20][20], np[20][20];
int sp, pp;
int S, T;

void add_edge(int from, int to, int cap) {
    G[from].push_back({to, (int)G[to].size(), cap});
    G[to].push_back({from, (int)G[from].size()-1, 0});
}

bool bfs_flow() {
    memset(level, -1, sizeof(level));
    queue<int> q;
    level[S] = 0;
    q.push(S);
    while (!q.empty()) {
        int v = q.front(); q.pop();
        for (auto &e : G[v]) {
            if (e.cap > 0 && level[e.to] < 0) {
                level[e.to] = level[v] + 1;
                q.push(e.to);
            }
        }
    }
    return level[T] >= 0;
}

int dfs_flow(int v, int f) {
    if (v == T) return f;
    for (int &i = iter[v]; i < (int)G[v].size(); ++i) {
        Edge &e = G[v][i];
        if (e.cap > 0 && level[v] < level[e.to]) {
            int d = dfs_flow(e.to, min(f, e.cap));
            if (d > 0) {
                e.cap -= d;
                G[e.to][e.rev].cap += d;
                return d;
            }
        }
    }
    return 0;
}

int max_flow() {
    int flow = 0;
    while (bfs_flow()) {
        memset(iter, 0, sizeof(iter));
        int f;
        while ((f = dfs_flow(S, 1e9)) > 0)
            flow += f;
    }
    return flow;
}

int n, t;

void wk(int a, int b) {
    for (int i = 1; i <= n; ++i)
        for (int j = 1; j <= n; ++j)
            dd[i][j] = 100000;
    deque<pair<int,int>> q;
    dd[a][b] = 0;
    q.push_back(make_pair(a,b));
    while (!q.empty()) {
        int x = q.front().first, y = q.front().second;
        q.pop_front();
        for (int i = 0; i < np[x][y].size(); ++i)
            for (int j = 0; j < ns[a][b].size(); ++j)
                add_edge(ns[a][b][j], np[x][y][i], 1);
        if (dd[x][y] == ir[x][y]) continue;
        for (int d = 0; d < 4; ++d) {
            int nx = x + dx[d], ny = y + dy[d];
            if (sc[nx][ny] != -1 && dd[nx][ny] > dd[x][y] + 1 && dd[x][y] + 1 <= ir[nx][ny]) {
                dd[nx][ny] = dd[x][y] + 1;
                q.push_back(make_pair(nx,ny));
            }
        }
    }
}

int main() {
    scanf("%d%d", &n, &t);
    for (int i = 1; i <= n; ++i)
        for (int j = 1; j <= n; ++j)
            ir[i][j] = t;
    for (int i = 1; i <= n; ++i)
        scanf("%s", s[i] + 1);
    for (int i = 1; i <= n; ++i)
        scanf("%s", p[i] + 1);
    int rx, ry;
    sp = 1; pp = 1000;
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= n; ++j) {
            if (s[i][j] == 'Z' || s[i][j] == 'Y')
                sc[i][j] = -1, ir[i][j] = 0;
            if (s[i][j] == 'Z')
                rx = i, ry = j, ir[i][j] = 0;
            if ('0' <= s[i][j] && s[i][j] <= '9')
                sc[i][j] = s[i][j] - '0';
            for (int k = 0; k < sc[i][j]; ++k)
                ns[i][j].push_back(sp++);
        }
    }
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= n; ++j) {
            if ('0' <= p[i][j] && p[i][j] <= '9')
                pc[i][j] = p[i][j] - '0';
            for (int k = 0; k < pc[i][j]; ++k)
                np[i][j].push_back(pp++);
        }
    }
    deque<pair<int,int>> q;
    q.push_back(make_pair(rx, ry));
    while (!q.empty()) {
        rx = q.front().first; ry = q.front().second;
        q.pop_front();
        int nx, ny;
        for (int d = 0; d < 4; ++d) {
            nx = rx + dx[d];
            ny = ry + dy[d];
            if (ir[nx][ny] > ir[rx][ry] + 1 && sc[nx][ny] != -1) {
                ir[nx][ny] = ir[rx][ry] + 1;
                q.push_back(make_pair(nx, ny));
            }
        }
    }
    S = 0; T = 2000;
    for (int i = 1; i < sp; ++i)
        add_edge(S, i, 1);
    for (int i = 1000; i < pp; ++i)
        add_edge(i, T, 1);
    for (int i = 1; i <= n; ++i)
        for (int j = 1; j <= n; ++j)
            if (sc[i][j] > 0)
                wk(i, j);
    printf("%d", max_flow());
    return 0;
}
